insert into public.course_content_draft (course_id, what_you_build, what_you_learn, session, starter_code, test_it_out, troubleshooting, resources, tier, change_note)
values (
  17,
  $wyb$A folder-watching agent that detects new invoice PDFs, extracts structured fields (vendor, invoice number, dates, totals, line items) using the AI, validates the data -- including a check that line items actually sum to the stated total -- appends it to a Google Sheet, catches duplicate invoice numbers even when formatted differently, and sends a Slack alert for anything overdue.$wyb$,
  $wyl$[
  "Extract text from PDF invoices and design a structured-extraction prompt with a fixed schema",
  "Parse a JSON reply defensively, stripping a code fence the AI wasn't supposed to add",
  "Validate extracted data with a numeric consistency check, not just a missing-fields check",
  "Normalize identifiers before comparing them, so near-identical duplicates don't slip through",
  "Write rows to Google Sheets with gspread in a fixed column order",
  "Watch a filesystem folder for new files and catch up on any missed while offline"
]$wyl$::jsonb,
  $sess${
  "model": "Gemini 3.7 Flash or Claude Haiku 4.5 (your choice - see sdt_ai.py setup)",
  "totalTime": "140 min",
  "buildCount": 4,
  "whatYouNeed": [
    "A free Gemini API key (aistudio.google.com/apikey) OR your own Claude/Anthropic API key (console.anthropic.com/settings/keys)",
    "Python 3.10+ installed",
    "A Google Cloud service account JSON key, shared (Editor) with a Google Sheet you create called \"Invoice Tracker\"",
    "3-5 sample invoice PDFs (your own past invoices work fine)",
    "(Optional) A Slack Incoming Webhook URL for overdue alerts"
  ],
  "outcomes": [
    "Extract vendor, dates, totals, and line items from real PDF invoices as structured JSON",
    "Parse a JSON reply defensively, so a stray code fence never crashes the pipeline",
    "Validate extracted data with both a missing-fields check and a line-items-sum-to-total check",
    "Catch duplicate invoice numbers even when formatted differently across exports",
    "Log every invoice to a Google Sheet, and alert Slack the moment one is overdue",
    "Watch a folder automatically, catching up on anything missed while the script was offline"
  ],
  "builds": [
    {
      "number": 1,
      "title": "Set up sdt_ai.py, tracker sheet, and extraction schema",
      "time": "30 min",
      "description": "Decide what data you want before building the pipeline that produces it.",
      "steps": [
        {
          "instruction": "Create `sdt_ai.py` in your project folder with this code. You'll reuse this exact file, unmodified, in every future AI Builder project:",
          "prompt": "\"\"\"\nSocial Dev AI Builder - your connection to the AI.\n\nYou have TWO ways to power this file. Pick ONE and set it in your .env:\n\n  AI_PROVIDER=gemini    -> your own FREE Google Gemini API key\n  AI_PROVIDER=claude    -> your own Claude/Anthropic API key\n\nEvery project in this course calls ask_ai(...) the exact same way no\nmatter which one you pick - this file is the only place that changes.\n\nSETUP - OPTION 1: Gemini (free, no billing needed):\n\n  1. Go to https://aistudio.google.com/apikey and sign in with any Google\n     account. Click \"Create API key\" - free, no card required.\n  2. In the same folder as this file, create a file named exactly: .env\n  3. Put these two lines inside it:\n\n         AI_PROVIDER=gemini\n         GEMINI_API_KEY=paste_your_own_key_here\n\nSETUP - OPTION 2: Claude (if you already have a paid Claude account):\n\n  1. Go to https://console.anthropic.com/settings/keys and create an API\n     key. This needs billing set up on your Anthropic account - it is a\n     separate thing from a claude.ai Pro subscription, and is billed by\n     Anthropic based on what you actually use.\n  2. In your .env file, put these two lines instead:\n\n         AI_PROVIDER=claude\n         ANTHROPIC_API_KEY=paste_your_own_key_here\n\nNever share either key or put it on GitHub - each one is billed to YOUR\naccount. That's it. Every project in this course reuses this same file.\n\"\"\"\n\nimport os\nimport time\n\nimport requests\nfrom dotenv import load_dotenv\n\n# Reads the .env file sitting next to your project and loads your keys.\nload_dotenv()\n\n# gemini-3.7-flash first - the current stable/GA flash model. If it's\n# ever down (Google's free tier occasionally returns 503 \"high demand\"\n# on a single model for hours at a time), gemini-2.5-flash is a real\n# fallback, not a downgrade-and-forget: a different model is a\n# different capacity pool, so it's often still up during a\n# 3.7-specific outage. Set GEMINI_MODEL in .env to pin one specific\n# model instead and skip the fallback entirely.\n_env_model = os.environ.get(\"GEMINI_MODEL\")\nGEMINI_MODELS = [_env_model] if _env_model else [\"gemini-3.7-flash\", \"gemini-2.5-flash\"]\nGEMINI_URL_TEMPLATE = \"https://generativelanguage.googleapis.com/v1beta/models/{model}:generateContent\"\n\nCLAUDE_MODEL = os.environ.get(\"CLAUDE_MODEL\", \"claude-haiku-4-5\")\nANTHROPIC_URL = \"https://api.anthropic.com/v1/messages\"\nANTHROPIC_VERSION = \"2023-06-01\"\n\n# Gemini's free tier occasionally answers 503 (\"model overloaded\") during\n# busy periods - that's not your code being wrong, retrying a couple of\n# times almost always gets a real answer.\nMAX_ATTEMPTS = 3\nRETRY_DELAY_SECONDS = 3\n\n\nclass AIError(Exception):\n    \"\"\"Something went wrong talking to the AI. The message explains what.\"\"\"\n\n\ndef _get_provider():\n    \"\"\"\n    Reads AI_PROVIDER from .env. Falls back to guessing from whichever key\n    is actually present, so forgetting to set AI_PROVIDER explicitly\n    doesn't crash a setup that only has one key configured.\n    \"\"\"\n    provider = os.environ.get(\"AI_PROVIDER\", \"\").strip().lower()\n    if provider in (\"gemini\", \"claude\"):\n        return provider\n\n    if os.environ.get(\"GEMINI_API_KEY\"):\n        return \"gemini\"\n    if os.environ.get(\"ANTHROPIC_API_KEY\"):\n        return \"claude\"\n\n    raise AIError(\n        \"No AI provider configured.\\n\"\n        \"Add ONE of these pairs to your .env file:\\n\\n\"\n        \"    AI_PROVIDER=gemini\\n\"\n        \"    GEMINI_API_KEY=paste_your_free_key_here\\n\\n\"\n        \"  ...or...\\n\\n\"\n        \"    AI_PROVIDER=claude\\n\"\n        \"    ANTHROPIC_API_KEY=paste_your_own_key_here\\n\\n\"\n        \"Get a free Gemini key at https://aistudio.google.com/apikey\"\n    )\n\n\ndef _ask_gemini_model(model, api_key, payload):\n    \"\"\"\n    Tries ONE Gemini model, retrying up to MAX_ATTEMPTS times on a 503\n    (\"high demand\") before giving up on this model. Returns the parsed\n    result dict, or raises AIError - including a distinct AIError for a\n    503 that never cleared, so _ask_gemini() below can tell \"this model\n    is down, try the next one\" apart from every other failure.\n    \"\"\"\n    url = GEMINI_URL_TEMPLATE.format(model=model)\n\n    for attempt in range(MAX_ATTEMPTS):\n        try:\n            response = requests.post(url, params={\"key\": api_key}, json=payload, timeout=90)\n        except requests.RequestException:\n            raise AIError(\n                \"Could not reach Gemini. Check your internet connection and try again.\"\n            )\n\n        if response.status_code == 503:\n            if attempt < MAX_ATTEMPTS - 1:\n                time.sleep(RETRY_DELAY_SECONDS)\n                continue\n            raise AIError(f\"{model} is busy (503 - high demand)\")\n\n        if response.status_code == 429:\n            raise AIError(\n                \"Gemini says you've hit the free tier's rate limit. Wait a \"\n                \"minute and try again.\"\n            )\n\n        if response.status_code == 400:\n            raise AIError(\n                f\"Gemini rejected the request - double check your GEMINI_API_KEY \"\n                f\"is correct: {response.text[:300]}\"\n            )\n\n        if response.status_code != 200:\n            raise AIError(\n                f\"Gemini returned an error (status {response.status_code}): {response.text[:300]}\"\n            )\n\n        data = response.json()\n        try:\n            candidate = data[\"candidates\"][0]\n        except (KeyError, IndexError):\n            raise AIError(f\"Unexpected reply from Gemini: {data}\")\n\n        if candidate.get(\"finishReason\") == \"SAFETY\":\n            raise AIError(\"Gemini declined to answer (safety filter). Try rephrasing your prompt.\")\n\n        try:\n            text = candidate[\"content\"][\"parts\"][0][\"text\"]\n        except (KeyError, IndexError):\n            raise AIError(f\"Unexpected reply shape from Gemini: {data}\")\n\n        usage = data.get(\"usageMetadata\", {})\n        return {\n            \"text\": text,\n            \"input_tokens\": usage.get(\"promptTokenCount\"),\n            \"output_tokens\": usage.get(\"candidatesTokenCount\"),\n        }\n\n\ndef _ask_gemini(prompt, system=None, max_tokens=1000):\n    api_key = os.environ.get(\"GEMINI_API_KEY\")\n    if not api_key:\n        raise AIError(\n            \"AI_PROVIDER is set to gemini but no GEMINI_API_KEY was found.\\n\"\n            \"Get a free key at https://aistudio.google.com/apikey and add \"\n            \"it to .env:\\n\"\n            \"    GEMINI_API_KEY=paste_your_own_key_here\"\n        )\n\n    payload = {\n        \"contents\": [{\"role\": \"user\", \"parts\": [{\"text\": prompt}]}],\n        \"generationConfig\": {\"maxOutputTokens\": max_tokens},\n    }\n    if system:\n        payload[\"systemInstruction\"] = {\"parts\": [{\"text\": system}]}\n\n    # Try each model in GEMINI_MODELS in order - a 503 that survives every\n    # retry on one model falls through to the next, since a different\n    # model is a different capacity pool and is often still up during a\n    # model-specific outage. Any other kind of failure (bad key, rate\n    # limit, safety block) is raised immediately instead of wasted on a\n    # second model that would fail the exact same way.\n    last_problem = None\n    for model in GEMINI_MODELS:\n        try:\n            return _ask_gemini_model(model, api_key, payload)\n        except AIError as problem:\n            if \"high demand\" not in str(problem):\n                raise\n            last_problem = problem\n\n    raise AIError(\n        f\"Gemini was unavailable after trying {', '.join(GEMINI_MODELS)} ({last_problem}). \"\n        \"This happens sometimes on the free tier during high demand - wait \"\n        \"a minute and try again.\"\n    )\n\n\ndef _ask_claude(prompt, system=None, max_tokens=1000):\n    api_key = os.environ.get(\"ANTHROPIC_API_KEY\")\n    if not api_key:\n        raise AIError(\n            \"AI_PROVIDER is set to claude but no ANTHROPIC_API_KEY was found.\\n\"\n            \"Create one at https://console.anthropic.com/settings/keys and \"\n            \"add it to .env:\\n\"\n            \"    ANTHROPIC_API_KEY=paste_your_own_key_here\"\n        )\n\n    payload = {\n        \"model\": CLAUDE_MODEL,\n        \"max_tokens\": max_tokens,\n        \"messages\": [{\"role\": \"user\", \"content\": prompt}],\n    }\n    if system:\n        payload[\"system\"] = system\n\n    try:\n        response = requests.post(\n            ANTHROPIC_URL,\n            headers={\n                \"x-api-key\": api_key,\n                \"anthropic-version\": ANTHROPIC_VERSION,\n                \"Content-Type\": \"application/json\",\n            },\n            json=payload,\n            timeout=90,\n        )\n    except requests.RequestException:\n        raise AIError(\"Could not reach Claude. Check your internet connection and try again.\")\n\n    try:\n        data = response.json()\n    except ValueError:\n        raise AIError(f\"Unexpected reply from Claude (status {response.status_code}).\")\n\n    if response.status_code == 401:\n        raise AIError(\n            \"Claude rejected your ANTHROPIC_API_KEY - double check it was copied correctly.\"\n        )\n\n    if response.status_code == 429:\n        raise AIError(\"Claude says you've hit your rate or usage limit. Wait a moment and try again.\")\n\n    if \"error\" in data:\n        raise AIError(data[\"error\"].get(\"message\", str(data[\"error\"])))\n\n    text = \"\".join(\n        block.get(\"text\", \"\") for block in data.get(\"content\", []) if block.get(\"type\") == \"text\"\n    )\n    usage = data.get(\"usage\", {})\n    return {\n        \"text\": text,\n        \"input_tokens\": usage.get(\"input_tokens\"),\n        \"output_tokens\": usage.get(\"output_tokens\"),\n    }\n\n\ndef ask_ai_detailed(prompt, system=None, max_tokens=1000, project=None):\n    \"\"\"\n    Same as ask_ai, but returns the whole reply as a dict.\n\n        result = ask_ai_detailed(\"Summarise this\", max_tokens=200)\n        print(result[\"text\"])\n    \"\"\"\n    provider = _get_provider()\n    if provider == \"gemini\":\n        return _ask_gemini(prompt, system=system, max_tokens=max_tokens)\n    return _ask_claude(prompt, system=system, max_tokens=max_tokens)\n\n\ndef ask_ai(prompt, system=None, max_tokens=1000, project=None):\n    \"\"\"\n    Send a question to the AI and get the answer back as text.\n\n        answer = ask_ai(\"Write a haiku about Lagos traffic\")\n        print(answer)\n\n    prompt      - what you want the AI to do. This is the important part.\n    system      - optional. Sets the AI's role, e.g. \"You are a careful editor.\"\n    max_tokens  - roughly how long the answer may be. 1000 is plenty for most.\n    project     - unused, kept so call sites read the same across every\n                  project regardless of which AI is behind this file.\n\n    Works identically whichever provider your .env is set to - every\n    project in this course calls this one function and never needs to\n    know which AI is actually answering.\n\n    Returns the AI's answer as a plain string.\n    Raises AIError with a readable message if something is wrong.\n    \"\"\"\n    return ask_ai_detailed(prompt, system=system, max_tokens=max_tokens, project=project)[\"text\"]\n\n\nif __name__ == \"__main__\":\n    # Running this file directly checks that your setup works.\n    print(\"Testing your AI Builder connection...\\n\")\n    try:\n        provider = _get_provider()\n        result = ask_ai_detailed(\"Say hello in exactly five words.\", max_tokens=50)\n        print(f\"Provider: {provider}\")\n        print(\"The AI said:\", result[\"text\"])\n        print(\"\\nYour setup works. You are ready to build.\")\n    except AIError as problem:\n        print(\"Setup problem:\\n\")\n        print(problem)\n",
          "verify": "Don't run it yet - it needs the .env file from the next step first."
        },
        {
          "instruction": "Create `.env` in the same folder with ONE of the two setups below — pick whichever you're using, then replace the placeholder with your real key:",
          "prompt": "# OPTION 1: your own free Gemini key (recommended - no billing needed)\n# Get one free at https://aistudio.google.com/apikey - no credit card needed\nAI_PROVIDER=gemini\nGEMINI_API_KEY=paste_your_own_key_here\n\n# OPTION 2: your own Claude/Anthropic key (comment OPTION 1 out above,\n# uncomment these two lines instead - needs billing set up on your own\n# Anthropic account)\n# Get one at https://console.anthropic.com/settings/keys\n# AI_PROVIDER=claude\n# ANTHROPIC_API_KEY=paste_your_own_key_here\n\n# Google service account JSON key - download it from Google Cloud\n# Console and save it as service_account.json in this folder, then\n# share your \"Invoice Tracker\" sheet (Editor access) with its email\n\n# Optional - a Slack Incoming Webhook URL for overdue alerts\n# SLACK_WEBHOOK_URL=https://hooks.slack.com/services/...\n",
          "verify": "Run `python sdt_ai.py` - it should print which provider you're using, then `The AI said: ...`, and end with `Your setup works. You are ready to build.` If you see `No AI provider configured` instead, check that .env sits next to sdt_ai.py and that AI_PROVIDER plus its matching key are both uncommented."
        },
        {
          "instruction": "Create a Google Sheet called \"Invoice Tracker\" with a header row: vendor_name | invoice_number | date | due_date | total | currency | needs_review | missing_fields. Share it (Editor access) with your service account's email.",
          "verify": "Open your Invoice Tracker sheet and confirm the header row matches exactly - gspread will append rows below it in this column order."
        },
        {
          "instruction": "Put 3-5 sample invoice PDFs into an `invoices/` folder.",
          "verify": "Open one sample invoice PDF and try to manually find the vendor name, invoice number, date, due date, and total - note how consistent (or not) the formatting is across your samples."
        }
      ],
      "goFurther": "Deliberately pick one sample invoice with a messy layout (multiple columns, a logo where text usually starts) - you'll use it in Build 2 to see how the extraction handles imperfect input."
    },
    {
      "number": 2,
      "title": "Extract and validate invoice data",
      "time": "45 min",
      "description": "Turn raw invoice text into clean, consistent JSON, then check it before it ever reaches your tracker sheet - both for missing fields and for the numbers actually adding up.",
      "steps": [
        {
          "instruction": "Create `extract.py` with this code:",
          "prompt": "\"\"\"\nStep 1 of the Invoice Processing Agent.\n\nReads a PDF invoice and asks the AI to extract its data as JSON matching\na fixed schema. The JSON-parsing helper is deliberately defensive: real\nmodel replies sometimes wrap JSON in ```json code fences despite being\ntold not to, and this project would rather strip that cleanly than\ncrash on it.\n\"\"\"\n\nimport json\n\nfrom PyPDF2 import PdfReader\nfrom sdt_ai import ask_ai\n\nSCHEMA = \"\"\"{\n  \"vendor_name\": \"...\",\n  \"invoice_number\": \"...\",\n  \"date\": \"YYYY-MM-DD\",\n  \"due_date\": \"YYYY-MM-DD\",\n  \"total\": 0.00,\n  \"currency\": \"USD\",\n  \"line_items\": [{\"description\": \"...\", \"amount\": 0.00}]\n}\"\"\"\n\n# Stop sending PDF text after this many characters. A MONEY decision:\n# most invoices are 1-2 pages, and the fields this schema needs almost\n# always appear early - a 50-page contract with an invoice attached\n# shouldn't cost 10x more to extract from than a normal one-page invoice.\nMAX_CHARACTERS = 6000\n\n\ndef extract_pdf_text(pdf_path):\n    \"\"\"Reads all pages of a PDF and returns their combined text.\"\"\"\n    reader = PdfReader(pdf_path)\n    return \"\\n\".join(page.extract_text() or \"\" for page in reader.pages)\n\n\ndef build_prompt(invoice_text):\n    trimmed = invoice_text[:MAX_CHARACTERS]\n    return f\"\"\"Extract this invoice's data as JSON matching EXACTLY this shape:\n\n{SCHEMA}\n\nIf a field isn't present in the invoice, use an empty string \"\" for text\nfields or 0.00 for numbers - never guess a plausible-looking value.\n\nReturn ONLY the JSON object. No explanation, no markdown code fence.\n\nINVOICE TEXT:\n{trimmed}\"\"\"\n\n\ndef parse_json_reply(reply):\n    \"\"\"\n    Turns the AI's reply into a Python dict, tolerating a ```json code\n    fence around it even though the prompt asks for none.\n\n        parse_json_reply('```json\\\\n{\"vendor_name\": \"Acme\"}\\\\n```')\n        -> {\"vendor_name\": \"Acme\"}\n\n    Returns None (never raises) if the reply isn't valid JSON at all, so\n    extract_invoice() can report a clear error instead of an unhandled\n    JSONDecodeError crashing the whole batch.\n    \"\"\"\n    cleaned = reply.strip()\n    if cleaned.startswith(\"```\"):\n        lines = cleaned.splitlines()\n        lines = lines[1:]\n        if lines and lines[-1].strip() == \"```\":\n            lines = lines[:-1]\n        cleaned = \"\\n\".join(lines)\n\n    try:\n        return json.loads(cleaned)\n    except json.JSONDecodeError:\n        return None\n\n\ndef extract_invoice(pdf_path):\n    \"\"\"\n    The main function. Give it a PDF path, get back the extracted data\n    as a dict, or raises ValueError if the AI's reply wasn't valid JSON\n    at all - rare, but real, and worth a clear error over a crash deep\n    inside json.loads().\n    \"\"\"\n    text = extract_pdf_text(pdf_path)\n    prompt = build_prompt(text)\n    reply = ask_ai(prompt, max_tokens=1000, project=\"invoice-processing-agent\")\n\n    data = parse_json_reply(reply)\n    if data is None:\n        raise ValueError(\n            \"The AI's reply wasn't valid JSON.\\n\"\n            \"Run it again - this usually fixes itself.\\n\"\n            \"If it keeps happening, print(reply) to see what came back.\"\n        )\n\n    return data\n\n\nif __name__ == \"__main__\":\n    # Run this file on its own to check the JSON parsing works - no AI\n    # call, no credits spent:  python extract.py\n    print(\"Checking a clean JSON reply...\")\n    clean_reply = '{\"vendor_name\": \"Acme Corp\", \"total\": 150.00}'\n    result = parse_json_reply(clean_reply)\n    assert result == {\"vendor_name\": \"Acme Corp\", \"total\": 150.00}\n    print(\"  OK -\", result)\n\n    print(\"\\nChecking a reply wrapped in a ```json code fence (told not to, does it anyway)...\")\n    fenced_reply = '```json\\n{\"vendor_name\": \"Acme Corp\", \"total\": 150.00}\\n```'\n    result = parse_json_reply(fenced_reply)\n    assert result == {\"vendor_name\": \"Acme Corp\", \"total\": 150.00}\n    print(\"  OK - fence stripped correctly:\", result)\n\n    print(\"\\nChecking a plain ``` fence with no 'json' label...\")\n    plain_fenced = '```\\n{\"vendor_name\": \"Acme Corp\"}\\n```'\n    assert parse_json_reply(plain_fenced) == {\"vendor_name\": \"Acme Corp\"}\n    print(\"  OK\")\n\n    print(\"\\nChecking a reply that isn't JSON at all...\")\n    assert parse_json_reply(\"Sorry, I couldn't read that invoice clearly.\") is None\n    print(\"  OK - returned None instead of crashing\")\n\n    print(\"\\nAll parsing checks passed.\")\n",
          "verify": "Run `python extract.py` (no AI call, no credits spent - this only tests JSON parsing against fake replies). You should see a clean JSON reply parsed correctly, a ```json-fenced reply correctly stripped, a plain ``` fence also stripped, and a non-JSON reply correctly returning None instead of crashing - ending with `All parsing checks passed.`"
        },
        {
          "instruction": "Now run it on a real sample invoice:",
          "prompt": "python -c \"from extract import extract_invoice; import json; print(json.dumps(extract_invoice('invoices/your_sample.pdf'), indent=2))\"",
          "verify": "You should get back valid JSON matching the schema with realistic values pulled from your actual PDF."
        },
        {
          "instruction": "Create `validate.py` with this code:",
          "prompt": "\"\"\"\nStep 1 of the Invoice Processing Agent (continued) - validates extracted\ninvoice data and flags anything worth a human's attention before it's\nlogged to the tracker sheet.\n\"\"\"\n\nREQUIRED_FIELDS = [\"vendor_name\", \"invoice_number\", \"date\", \"total\"]\n\n# Line items rarely sum to the total to the exact cent (rounding on\n# per-item tax, for instance) - this tolerance avoids flagging every\n# single invoice over a 1-cent rounding difference while still catching\n# a genuinely wrong extraction.\nAMOUNT_TOLERANCE = 0.02\n\n\ndef missing_required_fields(data):\n    \"\"\"\n    Returns the list of required fields that are empty or missing.\n\n        missing_required_fields({\"vendor_name\": \"Acme\", \"total\": 0})\n        -> [\"invoice_number\", \"date\", \"total\"]\n\n    Treats a present-but-empty value (\"\" or 0) the same as a missing key -\n    the AI is told to use \"\" or 0.00 rather than guess, so an empty\n    value here means genuinely not found.\n    \"\"\"\n    missing = []\n    for field in REQUIRED_FIELDS:\n        value = data.get(field)\n        if not value:\n            missing.append(field)\n    return missing\n\n\ndef amount_mismatch(data):\n    \"\"\"\n    Returns True if the line items don't sum to roughly the stated\n    total - a real and common extraction error worth flagging rather\n    than trusting the extracted total blindly.\n\n        amount_mismatch({\"total\": 100.00, \"line_items\": [{\"amount\": 40}, {\"amount\": 40}]})\n        -> True  (40 + 40 = 80, not 100)\n\n    Returns False (not flagged) if there are no line items at all -\n    plenty of real invoices are extracted with just a total and no\n    itemization, and that alone isn't a sign of a bad extraction.\n    \"\"\"\n    line_items = data.get(\"line_items\") or []\n    if not line_items:\n        return False\n\n    items_sum = sum(item.get(\"amount\", 0) or 0 for item in line_items)\n    total = data.get(\"total\", 0) or 0\n    return abs(items_sum - total) > AMOUNT_TOLERANCE\n\n\ndef validate(data):\n    \"\"\"\n    The main function. Mutates and returns data with two extra fields:\n\n        data[\"needs_review\"]   - True if anything below is off\n        data[\"missing_fields\"] - comma-separated list of what's wrong\n\n    \"missing_fields\" also carries the string \"amount_mismatch\" when line\n    items don't sum to the total, even though that's not literally a\n    missing field - keeping this project to one flag field for finance\n    to scan, rather than several.\n    \"\"\"\n    missing = missing_required_fields(data)\n    if amount_mismatch(data):\n        missing.append(\"amount_mismatch\")\n\n    data[\"needs_review\"] = bool(missing)\n    data[\"missing_fields\"] = \", \".join(missing)\n    return data\n\n\nif __name__ == \"__main__\":\n    # Run this file on its own to check validation works - no AI call,\n    # no credits spent:  python validate.py\n    print(\"Checking a complete, consistent invoice...\")\n    complete = {\n        \"vendor_name\": \"Acme Corp\", \"invoice_number\": \"INV-001\", \"date\": \"2026-08-01\",\n        \"total\": 100.00, \"line_items\": [{\"amount\": 60.00}, {\"amount\": 40.00}],\n    }\n    result = validate(dict(complete))\n    assert result[\"needs_review\"] is False\n    assert result[\"missing_fields\"] == \"\"\n    print(\"  OK - needs_review is False, missing_fields is empty\")\n\n    print(\"\\nChecking an invoice missing required fields...\")\n    incomplete = {\"vendor_name\": \"\", \"invoice_number\": \"INV-002\", \"date\": \"2026-08-01\", \"total\": 50.00}\n    result = validate(dict(incomplete))\n    assert result[\"needs_review\"] is True\n    assert \"vendor_name\" in result[\"missing_fields\"]\n    print(\"  OK -\", result[\"missing_fields\"])\n\n    print(\"\\nChecking an invoice where line items don't sum to the total...\")\n    mismatched = {\n        \"vendor_name\": \"Acme\", \"invoice_number\": \"INV-003\", \"date\": \"2026-08-01\",\n        \"total\": 100.00, \"line_items\": [{\"amount\": 40.00}, {\"amount\": 40.00}],\n    }\n    result = validate(dict(mismatched))\n    assert result[\"needs_review\"] is True\n    assert \"amount_mismatch\" in result[\"missing_fields\"]\n    print(\"  OK -\", result[\"missing_fields\"], \"(40 + 40 = 80, not 100)\")\n\n    print(\"\\nChecking an invoice with no line items isn't flagged for that reason...\")\n    no_items = {\"vendor_name\": \"Acme\", \"invoice_number\": \"INV-004\", \"date\": \"2026-08-01\", \"total\": 100.00}\n    result = validate(dict(no_items))\n    assert \"amount_mismatch\" not in result[\"missing_fields\"]\n    print(\"  OK - no line items is not treated as a mismatch\")\n\n    print(\"\\nAll validation checks passed.\")\n",
          "verify": "Run `python validate.py`. You should see a complete/consistent invoice correctly pass with needs_review False, an incomplete one correctly flagged with the missing field named, a mismatched-total invoice correctly flagged with 'amount_mismatch', and an invoice with no line items at all correctly NOT flagged for that reason - ending with `All validation checks passed.`"
        }
      ],
      "goFurther": "🛠️ Try your messiest sample invoice from Build 1 - if text gets truncated at 6000 characters and loses the total, either raise MAX_CHARACTERS in extract.py or check whether the totals section reliably appears on the last page and extract that page separately."
