    {
      "number": 4,
      "title": "Watch the folder and alert on overdue invoices",
      "time": "35 min",
      "description": "The last step - no more manually running the script per file, and finance gets pinged the moment something is overdue.",
      "steps": [
        {
          "instruction": "Create `overdue.py` with this code:",
          "prompt": "\"\"\"\nStep 3 of the Invoice Processing Agent - alerts Slack when an invoice's\ndue date has passed.\n\"\"\"\n\nfrom datetime import date\n\nimport requests\n\n\ndef is_overdue(due_date_str, today=None):\n    \"\"\"\n    Returns True if due_date_str (YYYY-MM-DD) is before today.\n\n        is_overdue(\"2026-01-01\", today=date(2026, 9, 2)) -> True\n\n    Pure function - tested below with a fixed `today` so the test never\n    depends on what day it happens to run.\n\n    A blank or unparseable due_date is treated as NOT overdue rather\n    than raising - an invoice missing its due date is already flagged\n    by validate()'s needs_review, and shouldn't ALSO trigger a false\n    overdue alert on top of that.\n    \"\"\"\n    if not due_date_str:\n        return False\n    try:\n        due = date.fromisoformat(due_date_str)\n    except ValueError:\n        return False\n    today = today or date.today()\n    return due < today\n\n\ndef build_alert_message(data):\n    \"\"\"Pure function - the exact Slack message text for one overdue invoice.\"\"\"\n    return (\n        f\"Invoice {data.get('invoice_number', '(unknown)')} from \"\n        f\"{data.get('vendor_name', '(unknown vendor)')} is overdue \"\n        f\"(was due {data.get('due_date', '(unknown)')}), total: \"\n        f\"{data.get('currency', '')} {data.get('total', 0)}\"\n    )\n\n\ndef alert_if_overdue(data, webhook_url):\n    \"\"\"\n    Posts a Slack alert if data's due_date has passed. Does nothing (no\n    error) if webhook_url is empty or the invoice isn't overdue.\n    \"\"\"\n    if not webhook_url or not is_overdue(data.get(\"due_date\", \"\")):\n        return\n\n    try:\n        requests.post(webhook_url, json={\"text\": build_alert_message(data)}, timeout=10)\n    except requests.RequestException as problem:\n        print(f\"Could not reach Slack (invoice was still logged): {problem}\")\n\n\nif __name__ == \"__main__\":\n    # Run this file on its own to check the logic works - no webhook or\n    # network call needed:  python overdue.py\n    from datetime import date as _date\n\n    fixed_today = _date(2026, 9, 2)\n\n    print(\"Checking is_overdue()...\")\n    assert is_overdue(\"2026-08-01\", today=fixed_today) is True\n    print(\"  OK - a due date in the past is correctly flagged overdue\")\n\n    assert is_overdue(\"2026-12-01\", today=fixed_today) is False\n    print(\"  OK - a future due date is correctly NOT flagged\")\n\n    assert is_overdue(\"\", today=fixed_today) is False\n    print(\"  OK - a blank due date is correctly NOT flagged (validate() already covers that gap)\")\n\n    assert is_overdue(\"not-a-date\", today=fixed_today) is False\n    print(\"  OK - an unparseable due date is correctly NOT flagged instead of raising\")\n\n    print(\"\\nChecking build_alert_message()...\")\n    message = build_alert_message({\n        \"invoice_number\": \"INV-001\", \"vendor_name\": \"Acme Corp\",\n        \"due_date\": \"2026-08-01\", \"currency\": \"USD\", \"total\": 150.00,\n    })\n    assert \"INV-001\" in message and \"Acme Corp\" in message and \"150.0\" in message\n    print(\"  OK -\", message)\n\n    print(\"\\nAll checks passed.\")\n",
          "verify": "Run `python overdue.py`. You should see a past due date correctly flagged overdue, a future one correctly not flagged, a blank due date correctly not flagged, and an unparseable date correctly not flagged instead of raising - then the alert message text checked - ending with `All checks passed.`"
        },
        {
          "instruction": "Create `watcher.py` with this code:",
          "prompt": "\"\"\"\nStep 3 of the Invoice Processing Agent (continued) - watches the\ninvoices/ folder and processes any new PDF automatically.\n\"\"\"\n\nimport os\nimport time\n\nfrom watchdog.events import FileSystemEventHandler\nfrom watchdog.observers import Observer\n\n# A file appearing in a folder doesn't mean it's finished being written -\n# a slow upload or sync client can trigger on_created before all bytes\n# have landed. This delay gives that a moment to finish before PyPDF2\n# tries to read a half-written file.\nPROCESS_DELAY_SECONDS = 2\n\n\ndef is_pdf_file(path):\n    \"\"\"Pure function - tested below without touching the filesystem.\"\"\"\n    return path.lower().endswith(\".pdf\")\n\n\nclass InvoiceHandler(FileSystemEventHandler):\n    \"\"\"\n    Calls process_fn(path) for every new .pdf file created in the\n    watched folder. Kept as its own class so is_pdf_file() above can be\n    tested without ever starting a real filesystem watcher.\n    \"\"\"\n\n    def __init__(self, process_fn):\n        self.process_fn = process_fn\n\n    def on_created(self, event):\n        if event.is_directory or not is_pdf_file(event.src_path):\n            return\n        time.sleep(PROCESS_DELAY_SECONDS)\n        self.process_fn(event.src_path)\n\n\ndef start_watching(folder, process_fn):\n    \"\"\"\n    Watches folder forever, calling process_fn(path) for each new PDF.\n    Also processes any PDF already sitting in the folder at startup, so\n    invoices dropped in while the script wasn't running still get caught.\n    \"\"\"\n    for filename in os.listdir(folder):\n        if is_pdf_file(filename):\n            process_fn(os.path.join(folder, filename))\n\n    handler = InvoiceHandler(process_fn)\n    observer = Observer()\n    observer.schedule(handler, folder, recursive=False)\n    observer.start()\n\n    print(f\"Watching {folder}/ for new invoices. Press Ctrl+C to stop.\")\n    try:\n        while True:\n            time.sleep(1)\n    except KeyboardInterrupt:\n        observer.stop()\n    observer.join()\n\n\nif __name__ == \"__main__\":\n    # Run this file on its own to check the pure filtering logic works -\n    # no filesystem watcher started, no PDFs needed:  python watcher.py\n    assert is_pdf_file(\"invoice.pdf\") is True\n    assert is_pdf_file(\"INVOICE.PDF\") is True\n    assert is_pdf_file(\"readme.txt\") is False\n    assert is_pdf_file(\"invoice.pdf.tmp\") is False\n    print(\"is_pdf_file() correctly recognises .pdf files regardless of case, and rejects everything else.\")\n    print(\"\\nAll checks passed. To actually watch a folder, run main.py with no arguments (Build 4).\")\n",
          "verify": "Run `python watcher.py`. You should see confirmation that .pdf files are recognised regardless of case and everything else is rejected, ending with `All checks passed.`"
        },
        {
          "instruction": "Update `main.py` to replace its previous contents with this version, then start it in watch mode:",
          "prompt": "\"\"\"\nStep 4 of the Invoice Processing Agent - ties every piece together into\none pipeline you can run per-file or leave watching a folder forever.\n\nRun it with:  python main.py invoices/sample_invoice.pdf   (single file)\n          or:  python main.py                              (watch mode)\n\"\"\"\n\nimport os\nimport sys\n\nfrom dotenv import load_dotenv\nfrom duplicates import is_duplicate\nfrom extract import extract_invoice\nfrom overdue import alert_if_overdue\nfrom sdt_ai import AIError\nfrom sheets import append_invoice, get_existing_invoice_numbers, get_worksheet\nfrom validate import validate\nfrom watcher import start_watching\n\nload_dotenv()\n\n\ndef process_invoice(pdf_path, worksheet, webhook_url):\n    \"\"\"Runs the full pipeline for one PDF: extract, validate, dedupe, log, alert.\"\"\"\n    print(f\"Processing {pdf_path}...\")\n\n    try:\n        data = extract_invoice(pdf_path)\n    except AIError as problem:\n        print(f\"  AI request failed: {problem}\")\n        return\n    except ValueError as problem:\n        print(f\"  Could not extract: {problem}\")\n        return\n\n    data = validate(data)\n\n    existing = get_existing_invoice_numbers(worksheet)\n    if is_duplicate(data.get(\"invoice_number\", \"\"), existing):\n        print(f\"  Skipped - duplicate invoice number: {data.get('invoice_number')}\")\n        return\n\n    append_invoice(worksheet, data)\n    print(f\"  Logged: {data.get('vendor_name')} - {data.get('invoice_number')} (needs_review={data['needs_review']})\")\n\n    alert_if_overdue(data, webhook_url)\n\n\nif __name__ == \"__main__\":\n    worksheet = get_worksheet()\n    webhook_url = os.environ.get(\"SLACK_WEBHOOK_URL\", \"\")\n\n    if len(sys.argv) > 1:\n        process_invoice(sys.argv[1], worksheet, webhook_url)\n    else:\n        start_watching(\"invoices\", lambda path: process_invoice(path, worksheet, webhook_url))\n",
          "verify": "Run `python main.py` with no arguments - it should immediately process any PDFs already sitting in invoices/, then print 'Watching invoices/ for new invoices.' Drop a new sample PDF into the folder - within a couple seconds it should appear as a new row in the sheet."
        },
        {
          "instruction": "Create `overdue_check.py` with this code, then run it against the row you manually backdated in Build 3:",
          "prompt": "\"\"\"\nStep 4 of the Invoice Processing Agent (continued) - a separate script\nto run once a day, re-checking EVERY logged invoice's due date against\ntoday, not just newly-processed ones. An invoice logged weeks ago can\nbecome overdue at any time without any new PDF ever arriving.\n\"\"\"\n\nimport os\n\nfrom dotenv import load_dotenv\nfrom overdue import alert_if_overdue, is_overdue\nfrom sheets import get_worksheet\n\nload_dotenv()\n\n\ndef check_all_overdue(worksheet, webhook_url):\n    rows = worksheet.get_all_records()\n    overdue_count = 0\n    for row in rows:\n        alert_if_overdue(row, webhook_url)\n        if is_overdue(row.get(\"due_date\", \"\")):\n            overdue_count += 1\n    return overdue_count\n\n\nif __name__ == \"__main__\":\n    worksheet = get_worksheet()\n    webhook_url = os.environ.get(\"SLACK_WEBHOOK_URL\", \"\")\n    count = check_all_overdue(worksheet, webhook_url)\n    print(f\"Checked all logged invoices. {count} currently overdue.\")\n",
          "verify": "Run `python overdue_check.py` - it should post a Slack alert for the row you backdated, and print how many invoices are currently overdue."
        }
      ],
      "goFurther": "🛠️🛠️ Add a daily summary function that reads all rows, filters to needs_review == True, and posts one Slack message listing all of them - so finance can triage incomplete invoices in one batch instead of one alert at a time."
    }
